    "home.welcomeBack": "वापसी पर स्वागत है, {name}",
    "home.h1.l1": "आपकी स्वास्थ्य कहानी।",
    "home.h1.l2": "हमेशा आपके साथ।",
    "home.subtitle": "अपना मेडिकल इतिहास फिर कभी समझाने की ज़रूरत नहीं। 30 सेकंड में डॉक्टर के लिए तैयार।",

    "home.story.title.l1": "अब तक आपकी कहानी।",
    "home.story.title.l2": "हर विवरण मायने रखता है।",
    "home.story.subtitle": "जब सिस्टम भूल जाता है तब क्या होता है, और परिवार कीमत चुकाते हैं। आपके रिकॉर्ड यह सुनिश्चित करते हैं कि ऐसा कभी न हो।",
    "home.story.beat1.title": "पाँच मिनट। एक उम्र का इतिहास।",
    "home.story.beat1.text": "एक परिवार ER भागता है। उन्हें दशकों के मेडिकल इतिहास को समझाने के लिए पाँच मिनट मिलते हैं। कोई रिकॉर्ड नहीं। कोई संदर्भ नहीं। बस डर।",
    "home.story.beat2.title": "75 पन्ने। कोई निरंतरता नहीं।",
    "home.story.beat2.text": "मोटे फ़ोल्डरों में बिखरी रिपोर्ट्स। हर नया डॉक्टर नए टेस्ट कराता है। घड़ी फिर से शुरू होती है। बिल बढ़ता है। कुछ भी नहीं जुड़ता।",
    "home.story.beat3.title": "बहुत देर से पकड़ा गया।",
    "home.story.beat3.text": "धीमे बदलावों को कोई ट्रैक नहीं करता। स्थितियाँ चुपचाप बिगड़ती हैं। जब तक पकड़ी जाती हैं, तब तक रोकथाम संभव नहीं रहती।",

    "home.uploadFirst.title": "अपना पहला रिकॉर्ड अपलोड करें",
    "home.uploadFirst.sub": "आपकी कहानी यहाँ से शुरू होती है।",
