    "home.abha.title": "अपना ABHA हेल्थ ID जोड़ें",
    "home.abha.body": "अपना राष्ट्रीय स्वास्थ्य ID जोड़ें और सभी प्रदाताओं की सलाह स्वतः जुड़ जाएगी।",

    "home.why.title": "Vyana क्यों?",
    "home.why.body1": "2005 में, तिरुपुर के एक छोटे अस्पताल में, एक परिवार ने अपने प्रिय को खो दिया। इसलिए नहीं कि डॉक्टरों ने ध्यान नहीं दिया। बल्कि इसलिए कि किसी के पास रिकॉर्ड नहीं थे। न इतिहास। न संदर्भ। बस एक उम्र समझाने के लिए पाँच निराश मिनट।",
    "home.why.body2": "Vyana इसलिए है कि ऐसा फिर कभी न हो। आपके परिवार के साथ नहीं। किसी के साथ नहीं।",
    "home.why.cta.title": "हमारी पूरी कहानी पढ़ें",
    "home.why.cta.sub": "उत्पाद के पीछे का वादा।",

