    "home.welcomeBack": "மீண்டும் வரவேற்கிறோம், {name}",
    "home.h1.l1": "உங்கள் ஆரோக்கிய கதை.",
    "home.h1.l2": "எப்போதும் உங்களுடன்.",
    "home.subtitle": "உங்கள் மருத்துவ வரலாற்றை மீண்டும் விளக்க வேண்டாம். 30 விநாடிகளில் மருத்துவருக்கு தயார்.",

    "home.story.title.l1": "இதுவரை உங்கள் கதை.",
    "home.story.title.l2": "ஒவ்வொரு விவரமும் முக்கியம்.",
    "home.story.subtitle": "அமைப்பு மறக்கும்போது என்ன நடக்கிறது, குடும்பங்கள் விலை செலுத்துகின்றன. உங்கள் பதிவுகள் இது நடக்காமல் உறுதி செய்கின்றன.",
    "home.story.beat1.title": "ஐந்து நிமிடங்கள். ஒரு வாழ்க்கை வரலாறு.",
    "home.story.beat1.text": "ஒரு குடும்பம் அவசர அறைக்கு விரைகிறது. பத்து ஆண்டு மருத்துவ வரலாற்றை விளக்க ஐந்து நிமிடங்கள் கிடைக்கின்றன. பதிவுகள் இல்லை. சூழல் இல்லை. பயம் மட்டுமே.",
    "home.story.beat2.title": "75 பக்கங்கள். தொடர்ச்சி இல்லை.",
    "home.story.beat2.text": "தடிமனான கோப்புகளில் சிதறிய அறிக்கைகள். ஒவ்வொரு புதிய மருத்துவரும் புதிய பரிசோதனைகள் கேட்கிறார்கள். கடிகாரம் மீட்டமைக்கப்படுகிறது. எதுவும் இணைவதில்லை.",
    "home.story.beat3.title": "மிக தாமதமாக கண்டுபிடிக்கப்பட்டது.",
    "home.story.beat3.text": "மெதுவான மாற்றங்களை யாரும் கண்காணிப்பதில்லை. நிலைகள் அமைதியாக மோசமாகின்றன. கண்டுபிடிக்கப்படும்போது, தடுப்பு சாத்தியமில்லை.",

    "home.uploadFirst.title": "உங்கள் முதல் பதிவை பதிவேற்றவும்",
    "home.uploadFirst.sub": "உங்கள் கதை இங்கே தொடங்குகிறது.",
    "home.records.eyebrow": "இதுவரை உங்கள் கதை",
    "home.records.held": "பதிவு வைக்கப்பட்டது",
    "home.records.heldPlural": "பதிவுகள் வைக்கப்பட்டன",
    "home.records.tagline": "நீங்கள் சேமிக்கும் ஒவ்வொரு விவரமும் உங்கள் அடுத்த மருத்துவர் கேட்க வேண்டிய ஒரு குறைந்த கேள்வி.",
