    "home.quickActions": "விரைவு செயல்கள்",
    "home.shareDoctor": "மருத்துவருடன் பகிரவும்",
    "home.emergencyAccess": "அவசர அணுகல்",

    "home.abha.title": "உங்கள் ABHA சுகாதார ID-ஐ இணைக்கவும்",
    "home.abha.body": "உங்கள் தேசிய சுகாதார ID-ஐ இணைக்கவும், அனைத்து வழங்குநர்களின் ஆலோசனைகளும் தானாக இணைக்கப்படும்.",

    "home.why.title": "ஏன் Vyana?",
    "home.why.body1": "2005-இல், திருப்பூரின் ஒரு சிறிய மருத்துவமனையில், ஒரு குடும்பம் தங்கள் அன்புக்குரியவரை இழந்தது. மருத்துவர்கள் கவனிக்கவில்லை என்பதால் அல்ல. யாரிடமும் பதிவுகள் இல்லாததால். வரலாறு இல்லை. சூழல் இல்லை. ஒரு வாழ்க்கையை விளக்க ஐந்து நிராசை நிமிடங்கள் மட்டுமே.",
    "home.why.body2": "அது மீண்டும் நடக்காமல் இருக்க Vyana உள்ளது. உங்கள் குடும்பத்திற்கு அல்ல. யாருக்கும் அல்ல.",
    "home.why.cta.title": "எங்கள் முழு கதையை படியுங்கள்",
    "home.why.cta.sub": "தயாரிப்புக்கு பின்னால் உள்ள வாக்குறுதி.",

    "home.bottom.tagline": "உங்கள் மருத்துவ வரலாற்றை மீண்டும் விளக்க வேண்டாம்.",
    "home.required.title": "உங்கள் சுயவிவரத்தை முடிக்கவும்",
    "home.required.desc": "உங்கள் பதிவுகளை உங்களுடன் இணைத்து வைக்க உங்கள் பெயர் மற்றும் ஃபோன் மட்டுமே தேவை. ABHA ID மற்றும் பிற விவரங்களை எப்போது வேண்டுமானாலும் சேர்க்கலாம்.",
    "home.required.fullName": "முழு பெயர்",
    "home.required.phone": "ஃபோன் எண்",
    "home.required.saving": "சேமிக்கிறது...",
    "home.required.save": "சேமித்து தொடரவும்",
    "home.banner.title": "உங்கள் சுயவிவரத்தை அமைத்து முடிக்கவும்",
    "home.banner.body": "உங்கள் பராமரிப்பை தனிப்பயனாக்க உங்கள் பிறந்த தேதி மற்றும் ABHA ID சேர்க்கவும்.",
    "home.banner.complete": "முடிக்க →",

    "briefingHero.eyebrow": "30 விநாடிகள்",
    "briefingHero.title.l1": "எனக்கு",
    "briefingHero.title.l2": "மருத்துவர் வருகை உள்ளது.",
    "briefingHero.body": "உங்கள் மருத்துவர் ஒரு நிமிடத்திற்குள் படிக்கக்கூடிய ஒற்றை ஸ்க்ரோல் ஷீட். நிலைகள், என்ன மாறியது, மருந்துகள், பகிர தயார்.",
