    "cta.eyebrow": "தொடங்குங்கள்",
    "cta.title.l1": "ஒவ்வொரு குடும்பமும் தகுதியானது",
    "cta.title.l2": "அவர்களின் கதையை அறிந்த ஒரு மருத்துவருக்கு.",
    "cta.sub": "இப்போதே Vyana-வை முயற்சிக்கவும். நீங்கள் நாள்பட்ட நிலைமைகளை நிர்வகித்தாலும், வயதான பெற்றோரைக் கவனித்தாலும், ஒவ்வொரு புதிய மருத்துவமனையிலும் உங்கள் வரலாற்றை மீண்டும் சொல்லி சோர்வடைந்தாலும்.",
    "cta.button": "முன்கூட்டிய அணுகலைப் பெறுங்கள்",
    "cta.linkedin": "LinkedIn",
    "cta.footer.copyright": "© 2025 Vyana. ஒவ்வொரு நோயாளியும் அவர்களின் கதையை அறிந்த மருத்துவருக்கு தகுதியானவர்.",

    "briefing.title": "என் சுருக்கம்",
    "briefing.subtitle": "எந்த மருத்துவருடனும் பகிர உங்கள் மருத்துவ சுருக்கத்தை உருவாக்குங்கள்.",
    "briefing.cta.title": "மருத்துவர்-தயார் சுருக்கம்",
    "briefing.cta.desc": "AI உங்கள் பதிவுகள், வைட்டல்கள் மற்றும் மருந்துகளை பகுப்பாய்வு செய்து எந்த மருத்துவரும் 30 வினாடிகளில் படிக்கக்கூடிய சுருக்கத்தை உருவாக்குகிறது.",
    "briefing.cta.includeTitle": "உங்கள் சுருக்கத்தில் இவை இருக்கும்:",
