    "ec.wa.message": "🚨 அவசர சுகாதார அணுகல்\n\n{name}, நீங்கள் Vyana இல் எனது அவசர தொடர்பாக சேர்க்கப்பட்டுள்ளீர்கள்.\n\nஅவசர நேரத்தில், எனது சுகாதார பதிவுகளை (மருந்துகள், நிலைகள், ஒவ்வாமை, சமீபத்திய வருகைகள்) பார்க்க இந்த இணைப்பைத் திறக்கவும்:\n{link}\n\nஇந்த செய்தியைச் சேமிக்கவும். இணைப்பு 24/7 வேலை செய்கிறது மற்றும் கணக்கு தேவையில்லை.\n\n- {patient}",
