    "home.story.beat1.title": "ఐదు నిమిషాలు. ఒక జీవితకాల చరిత్ర.",
    "home.story.beat1.text": "ఒక కుటుంబం ER కు పరుగెత్తుతుంది. దశాబ్దాల చరిత్రను వివరించడానికి ఐదు నిమిషాలే. రికార్డులు లేవు. భయం మాత్రమే.",
    "home.story.beat2.title": "75 పేజీలు. కొనసాగింపు లేదు.",
    "home.story.beat2.text": "మందపాటి ఫోల్డర్‌లలో చెల్లాచెదురుగా ఉన్న నివేదికలు. ప్రతి కొత్త డాక్టర్ తాజా పరీక్షలు ఆర్డర్ చేస్తారు.",
    "home.story.beat3.title": "చాలా ఆలస్యంగా.",
    "home.story.beat3.text": "నెమ్మదిగా జరిగే మార్పులను ఎవరూ ట్రాక్ చేయరు. గుర్తించే సమయానికి, నివారణ సాధ్యం కాదు.",

    "home.uploadFirst.title": "మీ మొదటి రికార్డ్‌ను అప్‌లోడ్ చేయండి",
    "home.uploadFirst.sub": "మీ కథ ఇక్కడ ప్రారంభమవుతుంది.",
