    "home.abha.title": "మీ ABHA హెల్త్ ID ని కనెక్ట్ చేయండి",
    "home.abha.body": "మీ జాతీయ ఆరోగ్య IDని లింక్ చేయండి, అన్ని సంప్రదింపులు స్వయంచాలకంగా కనెక్ట్ అవుతాయి.",

    "home.why.title": "Vyana ఎందుకు?",
    "home.why.body1": "2005లో, తిరుపూర్‌లోని ఒక చిన్న ఆసుపత్రిలో, ఒక కుటుంబం ప్రియమైనవారిని కోల్పోయింది. డాక్టర్లు పట్టించుకోకపోవడం వల్ల కాదు. రికార్డులు లేకపోవడం వల్ల.",
    "home.why.body2": "అది మళ్లీ జరగకూడదని Vyana ఉంది. మీ కుటుంబానికి కాదు. ఎవరికీ కాదు.",
    "home.why.cta.title": "మా పూర్తి కథ చదవండి",
    "home.why.cta.sub": "ఉత్పత్తి వెనుక ఉన్న వాగ్దానం.",

    "home.bottom.tagline": "మీ వైద్య చరిత్రను మళ్లీ వివరించాల్సిన అవసరం లేదు.",
    "home.required.title": "మీ ప్రొఫైల్‌ను పూర్తి చేయండి",
    "home.required.desc": "మీ రికార్డులను మీతో అనుసంధానించడానికి మాకు మీ పేరు మరియు ఫోన్ మాత్రమే అవసరం. మీరు ఎప్పుడైనా ABHA ID మరియు ఇతర వివరాలను జోడించవచ్చు.",
    "home.required.fullName": "పూర్తి పేరు",
    "home.required.phone": "ఫోన్ నంబర్",
