    "cta.sub": "ఇప్పుడే Vyana ప్రయత్నించండి. మీరు దీర్ఘకాలిక పరిస్థితులను నిర్వహిస్తున్నా, వృద్ధ తల్లిదండ్రులను చూసుకుంటున్నా, లేదా ప్రతి కొత్త క్లినిక్‌లో మీ చరిత్రను పునరావృతం చేయడంలో అలసిపోయినా.",
