    "home.welcomeBack": "ফিরে আসায় স্বাগতম, {name}",
    "home.h1.l1": "আপনার স্বাস্থ্য কাহিনী।",
    "home.h1.l2": "সর্বদা আপনার সাথে।",
    "home.subtitle": "আপনার চিকিৎসা ইতিহাস আবার ব্যাখ্যা করার দরকার নেই। ৩০ সেকেন্ডে ডাক্তারের জন্য প্রস্তুত।",

    "home.story.title.l1": "এ পর্যন্ত আপনার গল্প।",
    "home.story.title.l2": "প্রতিটি বিবরণ গুরুত্বপূর্ণ।",
    "home.story.subtitle": "যখন সিস্টেম ভুলে যায় এবং পরিবার মূল্য চোকায়। আপনার রেকর্ড নিশ্চিত করে যে এটি কখনই ঘটবে না।",
    "home.story.beat1.title": "পাঁচ মিনিট। জীবনভর ইতিহাস।",
    "home.story.beat1.text": "একটি পরিবার ER-এ ছুটে যায়। দশকের চিকিৎসা ইতিহাস ব্যাখ্যা করতে পাঁচ মিনিট পায়। কোনো রেকর্ড নেই। শুধু ভয়।",
    "home.story.beat2.title": "৭৫ পৃষ্ঠা। কোনো ধারাবাহিকতা নেই।",
    "home.story.beat2.text": "পুরু ফোল্ডারে ছড়ানো রিপোর্ট। প্রতিটি নতুন ডাক্তার নতুন পরীক্ষা দেয়। ঘড়ি রিসেট হয়।",
    "home.story.beat3.title": "অনেক দেরিতে ধরা পড়ে।",
    "home.story.beat3.text": "ধীর পরিবর্তনগুলি কেউ ট্র্যাক করে না। ধরা পড়ার সময়, প্রতিরোধ আর সম্ভব নয়।",

    "home.uploadFirst.title": "আপনার প্রথম রেকর্ড আপলোড করুন",
